"""Tests verifying that PR body generated by RepoCrew contains complete test evidence."""
from backend import orchestrator
from backend.models import Issue, Run, TestResult


def test_pr_body_contains_test_evidence():
    issue = Issue(id=1, number=42, title="Fix date boundary issue")
    run = Run(id=101, issue_id=1, attempts=1)

    gate = {
        "score": 0.95,
        "threshold": 0.8,
        "allowed": True,
        "paths": ["miniutils/dates.py"],
        "checks": [
            {"name": "Tests pass in sandbox", "passed": True, "detail": "12 passed, 0 failed"},
            {"name": "Reviewer verdict", "passed": True, "detail": "APPROVE"},
        ],
    }

    test_res = TestResult(
        run_id=101,
        attempt=1,
        passed=True,
        passed_count=12,
        failed=0,
        total=12,
        engine="docker",
        detail="Bug fixed; 12 passed in isolated container",
    )

    review = {
        "verdict": "APPROVE",
        "notes": ["Clean boundary condition fix with no regressions."],
    }

    title, body = orchestrator.build_pr_content(run, issue, gate, test_res, review)

    assert title == "Fix #42: Fix date boundary issue"
    assert "## Test results (real pytest in the RepoCrew sandbox)" in body
    assert "Verdict: **PASS**" in body
    assert "12 passed, 0 failed" in body
    assert "engine: docker" in body
    assert "Bug fixed; 12 passed in isolated container" in body
    assert "Confidence score" in body
    assert "Opened by RepoCrew. Human review required before merge." in body
    # Confirm no merge language anywhere
    assert "auto-merge" not in body.lower()
